<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#e8dfca"><title>Big Rig Balance Yard</title>
<style>
:root{--paper:#f2ead8;--ink:#193b35;--red:#c64227;--gold:#e5b94f;--line:#193b3533}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#e8dfca;font:17px/1.55 Georgia,serif}button,select{font:inherit}button{cursor:pointer}a{color:inherit;text-underline-offset:4px}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid var(--red);outline-offset:4px}button:disabled{cursor:default;opacity:.5}.wrap{max-width:1220px;margin:auto;padding:26px 32px}nav,.mono,.eyebrow,button,select,.bay-label{font-family:'Courier New',monospace}nav{display:flex;justify-content:space-between;border-bottom:2px solid var(--ink);padding-bottom:13px;font-size:12px;gap:15px}nav a{text-decoration:none}.mast{display:grid;grid-template-columns:1.2fr 1fr;gap:50px;align-items:end;margin:35px 0 26px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:2px;color:var(--red);font-weight:bold}h1{font-size:clamp(50px,7vw,91px);font-weight:normal;letter-spacing:-4px;line-height:.91;margin:12px 0}h1 em{font-style:normal;color:var(--red)}.mast p{max-width:340px;margin-bottom:0}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px}.work{background:var(--paper);border:2px solid var(--ink);box-shadow:6px 6px 0 #193b3522;min-width:0}.dispatch{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px 22px;border-bottom:1px solid var(--line)}select{max-width:100%;background:transparent;color:var(--ink);padding:9px;border:1px solid var(--ink);font-size:13px}.ticket{padding:20px 22px 10px}.ticket h2{font-weight:normal;font-size:30px;line-height:1.15;margin:0 0 8px}.ticket p{font-size:15px;margin:0}.yard{padding:20px 18px 0;background:repeating-linear-gradient(0deg,transparent,transparent 26px,#193b3507 27px)}.deck{margin-left:36.4%;margin-right:15%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px}.slot{padding:7px 2px;min-height:88px;font-size:11px;border:2px dashed #193b3566;background:#e3d9bd;color:var(--ink);line-height:1.3;overflow-wrap:anywhere}.slot.filled{border-style:solid;background:var(--gold);box-shadow:inset 0 0 0 3px #f2ead866}.slot strong{display:block;font-size:17px}.slot small{font-size:10px}.bay-label{margin-left:36.4%;margin-right:15%;display:flex;justify-content:space-between;font-size:10px;padding:6px 0}.truck{width:100%;height:auto;display:block}.scales{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:15px 22px 22px}.scale{border-top:3px solid var(--ink);padding-top:9px}.scale b{font-family:'Courier New',monospace;font-size:26px}.scale small{display:block;font-size:12px}.track{height:9px;background:#d8cfb8;margin-top:9px}.fill{height:100%;width:0;background:var(--ink);transition:width .25s}.scale.over{color:var(--red)}.scale.over .fill{background:var(--red)}.cargo{padding:18px 22px;background:#e9dfc6;border-top:1px solid var(--line)}.cargo h3{font-size:12px;letter-spacing:1px;font-family:'Courier New',monospace;margin:0 0 12px}.crates{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.crate{border:1px solid var(--ink);background:var(--paper);color:var(--ink);padding:12px 3px;font-size:11px;line-height:1.4;min-height:73px}.crate b{display:block;font-size:19px}.crate[aria-pressed=true]{background:var(--ink);color:var(--paper);transform:translateY(-4px);box-shadow:0 4px 0 var(--red)}.crate.loaded{border-style:dashed}.actions{display:flex;flex-wrap:wrap;gap:8px;padding:16px 22px 0}button.action{border:1px solid var(--ink);color:var(--ink);background:transparent;padding:11px 14px;font-size:12px;min-height:44px}button.primary{background:var(--red);border-color:var(--red);color:#fff7e7}#status{padding:12px 22px 20px;margin:0;min-height:92px;font-size:15px}#status.good{color:#215c3a;font-weight:bold}aside{min-width:0}.portrait{margin:0;background:var(--ink);color:var(--paper);transform:rotate(1.5deg);box-shadow:5px 5px 0 #193b3522}.portrait img{display:block;width:100%;aspect-ratio:3/2;object-fit:cover}.portrait figcaption{padding:15px 18px;font-size:14px}.portrait strong{font-family:'Courier New',monospace;font-size:12px;letter-spacing:1px;display:block;margin-bottom:6px}.notes{padding:24px 8px}.notes h2{font-weight:normal;font-size:28px;margin:0 0 10px}.notes p{font-size:15px}.stamps{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.stamp{border:2px dashed #193b3555;border-radius:50%;width:44px;height:44px;display:grid;place-content:center;font:18px 'Courier New',monospace;opacity:.55}.stamp.done{border:2px solid var(--red);color:var(--red);opacity:1;transform:rotate(-12deg);background:var(--paper)}footer{margin-top:30px;padding-top:18px;border-top:1px solid var(--line);font-size:13px}.explain{font-size:13px;border-top:1px solid var(--line);padding-top:16px}details summary{cursor:pointer}details p{margin-top:10px}#next{display:none}#next.show{display:inline-block}@media(max-width:850px){.layout{grid-template-columns:1fr}.mast{gap:20px}aside{display:grid;grid-template-columns:1fr 1fr;gap:22px}.portrait{align-self:start}.notes{padding:0}}@media(max-width:540px){.wrap{padding:20px 15px}.mast{display:block;margin:26px 0}.mast p{font-size:16px;max-width:none}h1{letter-spacing:-2.5px}.layout{gap:28px}aside{grid-template-columns:1fr}.portrait{max-width:360px}.dispatch{padding:12px;flex-wrap:wrap}.ticket,.cargo{padding-left:14px;padding-right:14px}.yard{padding-left:8px;padding-right:8px}.slot{font-size:9px;min-height:82px}.slot strong{font-size:14px}.slot small{font-size:9px}.scales{padding:12px 14px 18px;gap:10px}.scale b{font-size:23px}.crate{font-size:10px}.crate b{font-size:17px}.actions{padding:14px 14px 0}#status{padding:12px 14px 18px}.notes{padding:0 4px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="wrap">
<nav><a href="./">← Chloe Reads Jon</a><span>YARD No. 7300 / OPEN DAILY</span></nav>
<header class="mast"><div><div class="eyebrow">An oversized pickup. A small physics problem.</div><h1>Big Rig<br><em>Balance Yard</em></h1></div><p>Four crates. Two axle scales. Put everything aboard without overloading either end. The truck is enormous. Your margin for error is less so.</p></header>
<div class="layout"><section class="work" aria-label="Truck loading puzzle">
<div class="dispatch"><label for="mission" class="mono" style="font-size:12px">DISPATCH ORDER</label><select id="mission" aria-label="Choose dispatch order"></select></div>
<div class="ticket"><h2 id="title"></h2><p id="brief"></p></div>
<div class="yard"><div class="deck" id="deck"></div><div class="bay-label"><span>← TOWARD CAB</span><span>TAIL →</span></div>
<svg class="truck" viewBox="0 0 700 160" role="img" aria-label="Schematic truck: front axle below the cab, rear axle just before bay three">
<path d="M5 148H695" stroke="#193b35" stroke-width="2"/>
<g id="chassis"><path d="M43 101V56L74 15H171V62H686V106H43Z" fill="#c64227" stroke="#193b35" stroke-width="3"/><path d="M78 25H125V56H57Z" fill="#9cbbb1"/><path d="M137 25H160V56H137Z" fill="#9cbbb1"/><path d="M180 68H680V94H180Z" fill="#e5b94f"/><path d="M64 72H112M139 66H154" stroke="#193b35" stroke-width="4"/><rect x="31" y="93" width="43" height="12" fill="#193b35"/><path d="M150 108H481" stroke="#193b35" stroke-width="10"/></g>
<g fill="#193b35" stroke="#f2ead8" stroke-width="4"><circle cx="110" cy="118" r="29"/><circle cx="450" cy="118" r="29"/></g><g fill="#b0a58a"><circle cx="110" cy="118" r="13"/><circle cx="450" cy="118" r="13"/></g>
<path d="M110 152V159M450 152V159" stroke="#193b35" stroke-width="3"/>
</svg></div>
<div class="scales"><div class="scale" id="frontScale"><span class="eyebrow">Front axle</span><div><b id="front">1,800</b> <span class="mono">kg</span></div><small id="frontLimit"></small><div class="track"><div class="fill" id="frontFill"></div></div></div><div class="scale" id="rearScale"><span class="eyebrow">Rear axle</span><div><b id="rear">1,200</b> <span class="mono">kg</span></div><small id="rearLimit"></small><div class="track"><div class="fill" id="rearFill"></div></div></div></div>
<div class="cargo"><h3>01 PICK A CRATE · 02 TAP A BAY</h3><div class="crates" id="crates"></div></div>
<div class="actions"><button class="action primary" id="check">Weigh &amp; dispatch →</button><button class="action" id="hint">Yard hint</button><button class="action" id="clear">Unload all</button><button class="action primary" id="next">Next order →</button></div>
<p id="status" role="status" aria-live="polite"></p>
</section>
<aside><figure class="portrait"><img src="?art=1" alt="Original screenprinted portrait of a huge red crew-cab pickup in a mountain loading yard"><figcaption><strong>THE INSPIRATION: INTERNATIONAL CXT</strong>Jon bookmarked this gigantic pickup in 2004. Our imaginary yard gives its oversized spirit a proper job.</figcaption></figure>
<div class="notes"><h2>Heavy goes where?</h2><p>Moving a crate toward the tail adds more weight to the rear axle. Behind that axle, it even takes some weight <em>off</em> the front. Think seesaw, with considerably better tires.</p><div class="stamps" id="stamps" aria-label="Completed orders"></div><p id="progress" class="mono" style="font-size:12px"></p><details class="explain"><summary>Peek under the scales</summary><p>Empty rig: 1,800 kg front + 1,200 kg rear. The four bays sit at 55%, 80%, 105%, and 130% of the wheelbase, measured from the front axle.</p><p>A crate's rear contribution is its mass × its position. The front gets the rest. Both axle limits must hold, and all four crates must be aboard.</p><p>This is a simplified static-balance puzzle. The cargo deck, weights, and limits are fictional, not CXT specifications or real loading advice.</p></details></div></aside></div>
<footer>Inspired by Jon's <a href="?source=1">International 7300 CXT post</a> (September 2004). Built by Chloe for a father and son who appreciate a ridiculous vehicle.<noscript><p>This puzzle needs JavaScript to operate the scales.</p></noscript></footer>
</main><script>
'use strict';
const missions=[
{title:'The garden-centre run',brief:'Soil, pots, tools, and a very important fern. All four need a ride.',names:['Soil','Pots','Tools','Fern'],weights:[600,400,200,100],solution:[0,2,1,3]},
{title:'A band with too much gear',brief:'The amplifier is heavier than the entire drum kit. Nobody is surprised.',names:['Amp','Drums','Lights','Guitars'],weights:[800,500,300,200],solution:[2,0,3,1]},
{title:'The tiny railway delivery',brief:'A model railway club has ordered some distinctly full-size supplies.',names:['Rails','Timber','Engine','Scenery'],weights:[900,700,300,100],solution:[1,3,0,2]},
{title:'A rather large picnic',brief:'The park festival needs a stove, tables, water, and a heroic quantity of cake.',names:['Stove','Tables','Water','Cake'],weights:[1100,600,400,200],solution:[3,0,2,1]},
{title:'Last load before sunset',brief:'Four workshop machines. A narrow allowance. One final dispatch stamp.',names:['Lathe','Press','Anvil','Bench'],weights:[1200,900,500,300],solution:[2,1,0,3]}
];
const positions=[.55,.8,1.05,1.3],$=id=>document.getElementById(id);
let current=0,slots=[null,null,null,null],selected=null,completed=[];
try{const saved=JSON.parse(localStorage.getItem('big-rig-yard-v1')||'[]');if(Array.isArray(saved))completed=saved.filter(n=>Number.isInteger(n)&&n>=0&&n<5);}catch{}
function weights(layout=slots){let front=1800,rear=1200;layout.forEach((crate,bay)=>{if(crate!==null){let mass=missions[current].weights[crate];rear+=mass*positions[bay];front+=mass*(1-positions[bay]);}});return {front:Math.round(front),rear:Math.round(rear)};}
function limits(){let target=weights(missions[current].solution);return{front:Math.ceil(target.front/25)*25+25,rear:Math.ceil(target.rear/25)*25+25};}
function report(message,good=false){$('status').textContent=message;$('status').classList.toggle('good',good);}
function save(){try{localStorage.setItem('big-rig-yard-v1',JSON.stringify(completed));}catch{}}
function render(){
 const m=missions[current],w=weights(),cap=limits();
 $('deck').innerHTML='';slots.forEach((crate,bay)=>{const b=document.createElement('button');b.className='slot'+(crate!==null?' filled':'');b.innerHTML=crate===null?'BAY '+(bay+1)+'<br><small>Tap to load</small>':'<small>'+m.names[crate]+'</small><strong>'+m.weights[crate]+'</strong>kg · BAY '+(bay+1);b.setAttribute('aria-label',crate===null?'Bay '+(bay+1)+', empty':m.names[crate]+', '+m.weights[crate]+' kilograms, bay '+(bay+1)+'. Tap to unload or replace.');b.onclick=()=>place(bay);$('deck').append(b);});
 $('crates').innerHTML='';m.names.forEach((name,i)=>{const b=document.createElement('button');b.className='crate'+(slots.includes(i)?' loaded':'');b.setAttribute('aria-pressed',selected===i?'true':'false');b.innerHTML=name+'<b>'+m.weights[i]+'</b>kg'+(slots.includes(i)?' · aboard':'');b.onclick=()=>{selected=selected===i?null:i;render();report(selected===null?'Selection cleared.':name+' selected. Tap a bay to load or move it.');};$('crates').append(b);});
 for(const end of ['front','rear']){$(end).textContent=w[end].toLocaleString('en-CA');$(end+'Limit').textContent='Limit '+cap[end].toLocaleString('en-CA')+' kg'+(w[end]>cap[end]?' · OVER':' · within limit');$(end+'Scale').classList.toggle('over',w[end]>cap[end]);$(end+'Fill').style.width=Math.min(100,w[end]/cap[end]*100)+'%';}
 $('stamps').innerHTML=missions.map((m,i)=>'<span class="stamp '+(completed.includes(i)?'done':'')+'" title="'+m.title+': '+(completed.includes(i)?'completed':'not completed')+'">'+(completed.includes(i)?'✓':i+1)+'</span>').join('');
 $('progress').textContent=new Set(completed).size+' OF 5 ORDERS STAMPED · SAVED ON THIS DEVICE';
}
function place(bay){$('next').classList.remove('show');if(selected===null){if(slots[bay]!==null){const name=missions[current].names[slots[bay]];slots[bay]=null;report(name+' unloaded.');}else report('Pick a crate below first, then tap this bay.');}else{const prior=slots.indexOf(selected),displaced=slots[bay];if(prior!==-1)slots[prior]=displaced;slots[bay]=selected;report(missions[current].names[selected]+' in bay '+(bay+1)+'.'+(displaced!==null&&prior===-1?' The other crate is back in the yard.':''));selected=null;}render();}
function load(i){current=i;slots=[null,null,null,null];selected=null;$('mission').value=i;$('title').textContent=missions[i].title;$('brief').textContent=missions[i].brief;$('next').classList.remove('show');render();report('Pick any crate, then tap a bay. Tap a loaded bay with no crate selected to unload it.');}
missions.forEach((m,i)=>{const o=document.createElement('option');o.value=i;o.textContent='0'+(i+1)+' / '+m.title;$('mission').append(o);});
$('mission').onchange=e=>load(Number(e.target.value));
$('clear').onclick=()=>load(current);
$('check').onclick=()=>{const w=weights(),cap=limits();if(slots.includes(null)){report('Not quite ready: all four crates need to be aboard.');return;}let over=[];for(const end of ['front','rear'])if(w[end]>cap[end])over.push(end+' axle is '+(w[end]-cap[end])+' kg over');if(over.length){report('Hold at the gate: '+over.join('; ')+'. Shift heavier cargo '+(w.rear>cap.rear?'toward the cab.':'toward the tail.'));return;}if(!completed.includes(current)){completed.push(current);save();}render();report(new Set(completed).size===5?'All five dispatched! You are officially the Yard Balance Boss. The fern sends its regards.':'DISPATCHED. Both axles within limits. That is one well-packed ridiculous truck.',true);if(current<4){$('next').textContent='Next order →';$('next').classList.add('show');}else if(new Set(completed).size<5){$('next').textContent='Next unfinished →';$('next').classList.add('show');}};
$('next').onclick=()=>load(current<4?current+1:missions.findIndex((_,i)=>!completed.includes(i)));
$('hint').onclick=()=>{const w=weights(),cap=limits();if(slots.includes(null)){report('Start with the heaviest crate near the cab. It is easier to adjust the lighter crates afterwards.');return;}if(w.rear>cap.rear)report('Rear too heavy? Swap a heavy crate near the tail with a lighter one nearer the cab.');else if(w.front>cap.front)report('Front too heavy? Move more mass toward the tail. Swapping two loaded bays keeps every crate aboard.');else report('Both scales look good. The dispatch button awaits your magnificent paperwork.');};
load(0);
</script></body></html>